output:
// Функция заполняет табличную часть документа "Заказ" остатками товаров
// из регистра накопления "ТоварныеЗапасы"
//
// Параметры:
//   ДокументОбъект - ДокументОбъект.Заказ - объект документа
//
// Возвращаемое значение:
//   Булево - Истина, если заполнение выполнено успешно
//
Функция ЗаполнитьТабличнуюЧастьОстатками(ДокументОбъект) Экспорт

    // Проверяем обязательные параметры документа
    Если НЕ ЗначениеЗаполнено(ДокументОбъект.Склад) Тогда
        Сообщить("Не указан склад! Заполнение табличной части невозможно.");
        Возврат Ложь;
    КонецЕсли;

    // Создаём запрос для получения остатков товаров
    Запрос = Новый Запрос;

    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар,
    |    ТоварныеЗапасыОстатки.КоличествоОстаток КАК Количество
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(
    |            &Период,
    |            Склад = &Склад
    |        ) КАК ТоварныеЗапасыОстатки
    |        ВНУТРЕННЕЕ СОЕДИНЕНИЕ Справочник.Товары КАК Товары
    |        ПО ТоварныеЗапасыОстатки.Товар = Товары.Ссылка
    |ГДЕ
    |    Товары.ВидТовара = ЗНАЧЕНИЕ(Перечисление.ВидыТоваров.Товар)
    |    И ТоварныеЗапасыОстатки.КоличествоОстаток > 0
    |УПОРЯДОЧИТЬ ПО
    |    ТоварныеЗапасыОстатки.Товар.Наименование";

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("Период", ДокументОбъект.Дата);
    Запрос.УстановитьПараметр("Склад", ДокументОбъект.Склад);

    // Выполняем запрос
    РезультатЗапроса = Запрос.Выполнить();

    // Очищаем табличную часть перед заполнением
    ДокументОбъект.Товары.Очистить();

    // Обходим результат запроса и добавляем строки в табличную часть
    Выборка = РезультатЗапроса.Выбрать();

    Пока Выборка.Следующий() Цикл
        НоваяСтрока = ДокументОбъект.Товары.Добавить();
        НоваяСтрока.Товар = Выборка.Товар;
        НоваяСтрока.Количество = Выборка.Количество;
    КонецЦикла;

    Возврат Истина;

КонецФункции

// Функция заполняет табличный документ задолженностью по контрагентам
//
// Параметры:
//  ТабДокумент - ТабличныйДокумент - документ для вывода отчета
//  Макет - ТабличныйДокумент - макет с секциями Шапка и Строка
//  Дата - Дата - дата, на которую получаются остатки
//
Процедура ЗаполнитьТабличныйДокумент(ТабДокумент, Макет, Дата) Экспорт

    // Создаем запрос для получения остатков по регистру Взаиморасчеты
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ВзаиморасчетыОстатки.Контрагент КАК Контрагент,
    |    ВзаиморасчетыОстатки.СуммаОстаток КАК Задолженность
    |ИЗ
    |    РегистрНакопления.Взаиморасчеты.Остатки(&Дата, ) КАК ВзаиморасчетыОстатки
    |УПОРЯДОЧИТЬ ПО
    |    Контрагент.Наименование
    |ИТОГИ
    |    СУММА(Задолженность)
    |ПО
    |    ОБЩИЕ";

    // Устанавливаем параметр запроса - дата среза остатков
    Запрос.УстановитьПараметр("Дата", Дата);

    // Выполняем запрос
    РезультатЗапроса = Запрос.Выполнить();

    // Получаем области макета
    ОбластьШапка = Макет.ПолучитьОбласть("Шапка");
    ОбластьСтрока = Макет.ПолучитьОбласть("Строка");

    // Выводим область шапки в табличный документ
    ТабДокумент.Вывести(ОбластьШапка);

    // Выбираем детальные записи из результата запроса
    ВыборкаДетальныеЗаписи = РезультатЗапроса.Выбрать(ОбходРезультатаЗапроса.ПоГруппировкам);

    // Обходим выборку и выводим строки
    Пока ВыборкаДетальныеЗаписи.Следующий() Цикл

        // Пропускаем группировку "Общие" (итоги)
        Если ВыборкаДетальныеЗаписи.Контрагент = Null Тогда
            Продолжить;
        КонецЕсли;

        // Заполняем параметры области строки
        ОбластьСтрока.Параметры.Контрагент = ВыборкаДетальныеЗаписи.Контрагент;
        ОбластьСтрока.Параметры.Задолженность = ВыборкаДетальныеЗаписи.Задолженность;

        // Выводим строку в табличный документ
        ТабДокумент.Вывести(ОбластьСтрока);

    КонецЦикла;

КонецПроцедуры

// Устанавливает склад во всех строках табличной части "Товары"
//
// Параметры:
//  ДокументОбъект - ДокументОбъект - Документ, в табличной части которого
//                                   необходимо установить склад
//
Процедура УстановитьСклад(ДокументОбъект) Экспорт

    // Проверяем, что склад заполнен
    Если НЕ ЗначениеЗаполнено(ДокументОбъект.Склад) Тогда
        Возврат;
    КонецЕсли;

    // Перебираем все строки табличной части "Товары"
    Для Каждого СтрокаТовары Из ДокументОбъект.Товары Цикл

        // Устанавливаем значение реквизита "СкладСтроки"
        СтрокаТовары.СкладСтроки = ДокументОбъект.Склад;

    КонецЦикла;

КонецПроцедуры

// Удаляет последнюю по времени запись регистра сведений КурсыВалют
//
// Параметры:
//   Валюта - СправочникСсылка.Валюты - Валюта, для которой удаляется запись
//
Процедура УдалитьПоследнююЗапись(Валюта) Экспорт

    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ ПЕРВЫЕ 1
    |    К.Период
    |ИЗ
    |    РегистрСведений.КурсыВалют К
    |ГДЕ
    |    К.Валюта = &Валюта
    |УПОРЯДОЧИТЬ ПО
    |    К.Период УБЫВ";

    Запрос.УстановитьПараметр("Валюта", Валюта);

    Результат = Запрос.Выполнить();

    Если Не Результат.Пустой() Тогда

        Выборка = Результат.Выбрать();
        Выборка.Следующий();

        МенеджерЗаписи = РегистрыСведений.КурсыВалют.СоздатьМенеджерЗаписи();
        МенеджерЗаписи.Валюта = Валюта;
        МенеджерЗаписи.Период = Выборка.Период;
        МенеджерЗаписи.Удалить();

    КонецЕсли;

КонецПроцедуры

// Функция возвращает список товаров указанного поставщика,
// для которых не установлены цены в регистре сведений
//
// Параметры:
//  Поставщик - СправочникСсылка.Поставщики - поставщик для фильтрации
//
// Возвращаемое значение:
//  СписокЗначений - список элементов справочника Товары без цен
//
Функция НеУстановленыЦены(Поставщик) Экспорт

    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ
    |    Товары.Ссылка
    |ИЗ
    |    Справочник.Товары КАК Товары
    |        ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.ЦеныТоваров КАК ЦеныТоваров
    |        ПО Товары.Ссылка = ЦеныТоваров.Товар
    |ГДЕ
    |    Товары.Поставщик = &Поставщик
    |    И ЦеныТоваров.Товар ЕСТЬ NULL
    |УПОРЯДОЧИТЬ ПО
    |    Товары.Наименование";

    Запрос.УстановитьПараметр("Поставщик", Поставщик);

    РезультатЗапроса = Запрос.Выполнить();

    СписокТоваров = Новый СписокЗначений;

    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        СписокТоваров.Добавить(Выборка.Ссылка);
    КонецЦикла;

    Возврат СписокТоваров;

КонецФункции

// Функция выгружает остатки товаров склада в JSON файл
//
// Параметры:
//   Склад - СправочникСсылка.Склады - Склад для выгрузки остатков
//           Если передана пустая ссылка или Неопределено - выгружаются остатки всех складов
//   МинимальныйОстаток - Число - Минимальное значение остатка для выгрузки
//   ФайлJson - Строка - Полный путь к файлу для записи JSON
//
// Возвращаемое значение:
//   Булево - Истина, если выгрузка выполнена успешно
//
Функция ВыгрузитьОстаткиСклада(Склад, МинимальныйОстаток, ФайлJson) Экспорт

    // Создаём запрос для получения остатков товаров
    Запрос = Новый Запрос;

    // Формируем текст запроса к виртуальной таблице остатков регистра
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Остатки.Товар.Код КАК Товар_Код,
    |    Остатки.Товар.Наименование КАК Товар_Наименование,
    |    ОКРУГЛЕНИЕ(Остатки.КоличествоОстаток, 0) КАК Остаток
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(
    |        ,
    |        &УсловиеПоСкладу
    |    ) КАК Остатки
    |ГДЕ
    |    Остатки.КоличествоОстаток >= &МинимальныйОстаток
    |УПОРЯДОЧИТЬ ПО
    |    Товар_Код";

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("МинимальныйОстаток", МинимальныйОстаток);

    // Формируем условие по складу
    Если Склад = Неопределено Или Склад.Пустая() Тогда
        // Выгружаем остатки по всем складам (без отбора по складу)
        Запрос.Текст = СтрЗаменить(Запрос.Текст, "&УсловиеПоСкладу", "ИСТИНА");
    Иначе
        // Выгружаем остатки по указанному складу
        Запрос.Текст = СтрЗаменить(Запрос.Текст, "&УсловиеПоСкладу", "Склад = &Склад");
        Запрос.УстановитьПараметр("Склад", Склад);
    КонецЕсли;

    // Выполняем запрос и получаем выборку
    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    // Создаём объект для записи JSON
    ЗаписьJSON = Новый ЗаписьJSON;
    ПараметрыЗаписиJSON = Новый ПараметрыЗаписиJSON(Символы.Табуляции);

    ЗаписьJSON.УстановитьСтроку(ПараметрыЗаписиJSON);

    // Начинаем запись массива JSON
    ЗаписатьJSON(ЗаписьJSON, Новый Массив);

    // Обходим выборку и записываем каждый товар
    Пока Выборка.Следующий() Цикл
        СтруктураТовара = Новый Структура;
        СтруктураТовара.Вставить("Товар_Код", Выборка.Товар_Код);
        СтруктураТовара.Вставить("Товар_Наименование", Выборка.Товар_Наименование);
        СтруктураТовара.Вставить("Остаток", Число(Выборка.Остаток));

        ЗаписатьJSON(ЗаписьJSON, СтруктураТовара);
    КонецЦикла;

    // Завершаем массив JSON
    ЗаписьJSON.ЗаписатьКонецМассива();

    // Получаем JSON строку
    JSONСтрока = ЗаписьJSON.Закрыть();

    // Убираем лишнюю обёртку массива вручную (для красивого форматирования)
    // Первый символ "[" и последний "]"
    Если СтрДлина(JSONСтрока) > 2 Тогда
        JSONСтрока = Сред(JSONСтрока, 2, СтрДлина(JSONСтрока) - 2);
        JSONСтрока = "[" + Символы.ПС + JSONСтрока + Символы.ПС + "]";
    КонецЕсли;

    // Записываем JSON в файл
    Попытка
        ЗаписьТекста = Новый ЗаписьТекста(ФайлJson, КодировкаТекста.UTF8);
        ЗаписьТекста.Записать(JSONСтрока);
        ЗаписьТекста.Закрыть();
        Возврат Истина;
    Исключение
        ЗаписьЖурналаРегистрации(
            "ВыгрузкаОстатковСклада",
            УровеньЖурналаРегистрации.Ошибка,
            ,
            ,
            "Ошибка записи файла: " + ПодробноеПредставлениеОшибки(ИнформацияОбОшибке())
        );
        Возврат Ложь;
    КонецПопытки;

КонецФункции

// Функция фильтрует строки таблицы значений по заданным параметрам
// Параметры:
//   Таблица - ТаблицаЗначений - исходная таблица с колонками: Склад, Товар, Количество
//   Склад - Произвольный - значение для фильтрации по колонке "Склад"
//   Наименование - Строка - подстрока для поиска в реквизите "Товар.Наименование"
//
// Возвращаемое значение:
//   ТаблицаЗначений - отфильтрованная таблица
//
Функция ВыбратьСтрокиТаблицы(Таблица, Склад, Наименование) Экспорт

    // Создаем запрос с менеджером временных таблиц
    Запрос = Новый Запрос;
    Запрос.МенеджерВременныхТаблиц = Новый МенеджерВременныхТаблиц;

    // Помещаем таблицу значений во временную таблицу
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ИсходнаяТаблица.Склад,
    |    ИсходнаяТаблица.Товар,
    |    ИсходнаяТаблица.Количество
    |ПОМЕСТИТЬ ВременнаяТаблица
    |ИЗ
    |    &ИсходнаяТаблица КАК ИсходнаяТаблица";

    Запрос.УстановитьПараметр("ИсходнаяТаблица", Таблица);
    Запрос.Выполнить();

    // Формируем шаблон для поиска подстроки в наименовании
    ШаблонПоиска = "%" + Наименование + "%";

    // Выбираем данные с учетом условий фильтрации
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ВременнаяТаблица.Склад,
    |    ВременнаяТаблица.Товар,
    |    ВременнаяТаблица.Количество
    |ИЗ
    |    ВременнаяТаблица КАК ВременнаяТаблица
    |ГДЕ
    |    ВременнаяТаблица.Склад = &Склад
    |    И ВременнаяТаблица.Товар.Наименование ПОДОБНО &ШаблонПоиска";

    Запрос.УстановитьПараметр("Склад", Склад);
    Запрос.УстановитьПараметр("ШаблонПоиска", ШаблонПоиска);

    РезультатЗапроса = Запрос.Выполнить();
    Результат = РезультатЗапроса.Выгрузить();

    Возврат Результат;

КонецФункции

// Функция возвращает таблицу значений с товарами, которые были на складе на Дата1,
// но отсутствуют на складе на Дата2
//
// Параметры:
//   Дата1 - Дата - Дата начального среза остатков
//   Дата2 - Дата - Дата конечного среза остатков
//
// Возвращаемое значение:
//   ТаблицаЗначений - колонки: Товар, Количество
//
Функция УшедшийТовар(Дата1, Дата2) Экспорт

    Запрос = Новый Запрос;

    // Устанавливаем параметры запроса - получаем остатки на конец дня
    Запрос.УстановитьПараметр("Дата1", КонецДня(Дата1));
    Запрос.УстановитьПараметр("Дата2", КонецДня(Дата2));

    Запрос.Текст =
    "ВЫБРАТЬ
    |    ОстаткиНаДату1.Товар,
    |    СУММА(ОстаткиНаДату1.КоличествоОстаток) КАК Количество
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&Дата1, ) КАК ОстаткиНаДату1
    |        ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.ТоварныеЗапасы.Остатки(&Дата2, ) КАК ОстаткиНаДату2
    |        ПО ОстаткиНаДату1.Товар = ОстаткиНаДату2.Товар
    |ГДЕ
    |    ОстаткиНаДату2.Товар ЕСТЬ NULL
    |СГРУППИРОВАТЬ ПО
    |    ОстаткиНаДату1.Товар
    |УПОРЯДОЧИТЬ ПО
    |    ОстаткиНаДату1.Товар.Наименование";

    РезультатЗапроса = Запрос.Выполнить();
    ТаблицаРезультата = РезультатЗапроса.Выгрузить();

    Возврат ТаблицаРезультата;

КонецФункции

// Функция возвращает таблицу значений с контрагентами,
// имеющими просроченную задолженность
//
// Параметры:
//  Дата        - Дата - Дата, на которую определяется задолженность
//  МинДолг     - Число - Минимальная сумма долга для отбора
//  СрокДолга   - Число - Срок в днях, после которого долг считается просроченным
//
// Возвращаемое значение:
//  ТаблицаЗначений - колонки: Контрагент, ДолгВсего, ДолгПросроченный, ДатаОбразованияДолга
//
Функция ПросроченныеДолги(Дата, МинДолг, СрокДолга) Экспорт

    // Создаем таблицу значений для результата
    Результат = Новый ТаблицаЗначений;
    Результат.Колонки.Добавить("Контрагент",             Новый ОписаниеТипов("СправочникСсылка.Контрагенты"));
    Результат.Колонки.Добавить("ДолгВсего",              Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
    Результат.Колонки.Добавить("ДолгПросроченный",       Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
    Результат.Колонки.Добавить("ДатаОбразованияДолга",  Новый ОписаниеТипов("Дата",,, Новый КвалификаторыДаты(Дата)));

    // Проверяем параметры
    Если НЕ ЗначениеЗаполнено(Дата) Тогда
        Возврат Результат;
    КонецЕсли;

    Если СрокДолга <= 0 Тогда
        Возврат Результат;
    КонецЕсли;

    // Вычисляем начальную дату анализа
    НачалоПериода = Дата - СрокДолга * 86400; // 86400 секунд в сутках

    Запрос = Новый Запрос;
    Запрос.Текст = 
    |ВЫБРАТЬ
    |    ВзаиморасчетыОстатки.Контрагент,
    |    ВЫБОР
    |        КОГДА ВзаиморасчетыОстатки.СуммаОстаток > 0
    |            ТОГДА ВзаиморасчетыОстатки.СуммаОстаток
    |        ИНАЧЕ 0
    |    КОНЕЦ КАК ДолгВсего
    |ПОМЕСТИТЬ Остатки
    |ИЗ
    |    РегистрНакопления.Взаиморасчеты.Остатки(&Дата, ) КАК ВзаиморасчетыОстатки
    |ГДЕ
    |    ВзаиморасчетыОстатки.СуммаОстаток > 0
    |
    |ИНДЕКСИРОВАТЬ ПО
    |    Контрагент
    |;
    |
    |ВЫБРАТЬ
    |    Остатки.Контрагент,
    |    Остатки.ДолгВсего,
    |    ВЫБОР
    |        КОГДА ЕСТЬNULL(Обороты.ПриходЗаПериод, 0) >= Остатки.ДолгВсего
    |            ТОГДА 0
    |        КОГДА ЕСТЬNULL(Обороты.ПриходЗаПериод, 0) = 0
    |            ТОГДА Остатки.ДолгВсего
    |        ИНАЧЕ Остатки.ДолгВсего - ЕСТЬNULL(Обороты.ПриходЗаПериод, 0)
    |    КОНЕЦ КАК ДолгПросроченный,
    |    &НачалоПериода КАК ДатаОбразованияДолга
    |ИЗ
    |    Остатки КАК Остатки
    |    ЛЕВОЕ СОЕДИНЕНИЕ (
    |        ВЫБРАТЬ
    |            ВзаиморасчетыОбороты.Контрагент,
    |            СУММА(ВзаиморасчетыОбороты.СуммаПриход) КАК ПриходЗаПериод
    |        ИЗ
    |            РегистрНакопления.Взаиморасчеты.Обороты(&НачалоПериода, &Дата, , ) КАК ВзаиморасчетыОбороты
    |        СГРУППИРОВАТЬ ПО
    |            ВзаиморасчетыОбороты.Контрагент
    |    ) КАК Обороты
    |    ПО Остатки.Контрагент = Обороты.Контрагент
    |ГДЕ
    |    Остатки.ДолгВсего >= &МинДолг
    |    И ВЫБОР
    |        КОГДА ЕСТЬNULL(Обороты.ПриходЗаПериод, 0) >= Остатки.ДолгВсего
    |            ТОГДА ЛОЖЬ
    |        ИНАЧЕ ИСТИНА
    |    КОНЕЦ
    |УПОРЯДОЧИТЬ ПО
    |    Остатки.Контрагент.Наименование
    |АВТОУПОРЯДОЧИВАНИЕ
    |";

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("Дата",            Дата);
    Запрос.УстановитьПараметр("МинДолг",         МинДолг);
    Запрос.УстановитьПараметр("СрокДолга",       СрокДолга);
    Запрос.УстановитьПараметр("НачалоПериода",   НачалоПериода);

    РезультатЗапроса = Запрос.Выполнить();

    Если НЕ РезультатЗапроса.Пустой() Тогда
        Результат = РезультатЗапроса.Выгрузить();
    КонецЕсли;

    Возврат Результат;

КонецФункции

// Функция создает движения регистра накопления "Продажи" по документу "РасходТовара"
// Параметры:
//   ДокументСсылка - ДокументСсылка.РасходТовара - ссылка на документ
//
Функция СоздатьДвиженияРегистраПродажи(ДокументСсылка) Экспорт

    // Создаем набор записей регистра накопления "Продажи"
    НаборЗаписей = РегистрыНакопления.Продажи.СоздатьНаборЗаписей();

    // Устанавливаем отбор по регистратору (документу)
    // Это позволяет работать только с движениями данного документа
    НаборЗаписей.Отбор.Регистратор.Установить(ДокументСсылка);

    // Записываем пустой набор записей
    // При Замещение = Истина удаляются все существующие записи по данному регистратору
    НаборЗаписей.Записать(Истина);

    // Проверяем, что документ проведен
    // Если документ не проведен, движения не создаем
    Если НЕ ДокументСсылка.Проведен Тогда
        Возврат Истина;
    КонецЕсли;

    // Получаем данные документа
    РеквизитыДокумента = ОбщегоНазначения.ЗначенияРеквизитовОбъекта(
        ДокументСсылка, 
        "Дата, Контрагент"
    );

    // Получаем табличную часть "Товары" документа
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Товары.Номенклатура,
    |    Товары.Количество,
    |    Товары.Сумма
    |ИЗ
    |    Документ.РасходТовара.Товары КАК Товары
    |ГДЕ
    |    Товары.Ссылка = &Ссылка";

    Запрос.УстановитьПараметр("Ссылка", ДокументСсылка);

    РезультатЗапроса = Запрос.Выполнить();

    // Если в табличной части нет строк, возвращаем успех
    Если РезультатЗапроса.Пустой() Тогда
        Возврат Истина;
    КонецЕсли;

    // Получаем выборку из результата запроса
    Выборка = РезультатЗапроса.Выбрать();

    // Заполняем набор записей новыми движениями
    Пока Выборка.Следующий() Цикл

        // Добавляем новую запись в набор записей
        Запись = НаборЗаписей.Добавить();

        // Заполняем измерения регистра
        // Измерения - обязательные поля для идентификации записи
        Запись.Номенклатура = Выборка.Номенклатура;
        Запись.Контрагент   = РеквизитыДокумента.Контрагент;

        // Заполняем ресурсы регистра
        // Ресурсы - числовые показатели, по которым считаются итоги
        Запись.Количество = Выборка.Количество;
        Запись.Сумма      = Выборка.Сумма;

        // Заполняем служебные поля движения
        // Период - дата движения (совпадает с датой документа)
        Запись.Период = РеквизитыДокумента.Дата;

        // Вид движения - определяет тип движения (приход/расход)
        // Для регистра остатков: ВидДвиженияНакопления.Приход или .Расход
        // Для регистра оборотов: вид движения не указывается
        Запись.ВидДвижения = ВидДвиженияНакопления.Приход;

    КонецЦикла;

    // Записываем заполненный набор записей
    // При Замещение = Истина старые записи были удалены в начале функции
    НаборЗаписей.Записать(Ложь);

    Возврат Истина;

КонецФункции

// Функция заменяет номенклатуру в табличной части "Товары" документов "Заказ"
// НоменклатураИсточник - заменяемая номенклатура
// НоменклатураЗамены - номенклатура на которую выполняется замена
// ДатаС, ДатаПо - интервал дат документов
Функция ЗаменитьНоменклатуру(НоменклатураИсточник, НоменклатураЗамены, ДатаС, ДатаПо) Экспорт

    // Проверка параметров
    Если НоменклатураИсточник = Неопределено Или НоменклатураИсточник.Пустая() Тогда
        ВызватьИсключение "Не указана номенклатура источник";
    КонецЕсли;

    Если НоменклатураЗамены = Неопределено Или НоменклатураЗамены.Пустая() Тогда
        ВызватьИсключение "Не указана номенклатура замены";
    КонецЕсли;

    // Создаём запрос для поиска проведённых документов с искомой номенклатурой
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ЗаказТовары.Ссылка КАК Ссылка
    |ИЗ
    |    Документ.Заказ.Товары КАК ЗаказТовары
    |ГДЕ
    |    ЗаказТовары.Ссылка.Дата МЕЖДУ &ДатаС И &ДатаПо
    |    И ЗаказТовары.Товар = &НоменклатураИсточник
    |    И ЗаказТовары.Ссылка.ПометкаУдаления = ЛОЖЬ
    |    И ЗаказТовары.Ссылка.Проведен = ИСТИНА
    |
    |СГРУППИРОВАТЬ ПО
    |    ЗаказТовары.Ссылка";

    Запрос.УстановитьПараметр("ДатаС", ДатаС);
    Запрос.УстановитьПараметр("ДатаПо", ДатаПо);
    Запрос.УстановитьПараметр("НоменклатураИсточник", НоменклатураИсточник);

    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    ОбработаноДокументов = 0;

    Пока Выборка.Следующий() Цикл

        ДокументСсылка = Выборка.Ссылка;

        Попытка
            ДокументОбъект = ДокументСсылка.ПолучитьОбъект();
        Исключение
            Сообщить("Не удалось получить объект документа " + ДокументСсылка + ": " + ПодробноеПредставлениеОшибки(ИнформацияОбОшибке()));
            Продолжить;
        КонецПопытки;

        Если ДокументОбъект = Неопределено Тогда
            Продолжить;
        КонецЕсли;

        // Запоминаем состояние проведения ДО изменения
        БылПроведён = ДокументОбъект.Проведен;

        БылаЗамена = Ложь;

        // Обрабатываем табличную часть "Товары"
        Для Каждого СтрокаТЧ Из ДокументОбъект.Товары Цикл
            Если СтрокаТЧ.Товар = НоменклатураИсточник Тогда
                СтрокаТЧ.Товар = НоменклатураЗамены;
                БылаЗамена = Истина;
            КонецЕсли;
        КонецЦикла;

        // Если замена была выполнена - записываем документ
        Если БылаЗамена Тогда

            Попытка

                Если БылПроведён Тогда
                    ДокументОбъект.Записать(РежимЗаписиДокумента.Проведение);
                Иначе
                    ДокументОбъект.Записать(РежимЗаписиДокумента.Запись);
                КонецЕсли;

                ОбработаноДокументов = ОбработаноДокументов + 1;

            Исключение
                Сообщить("Ошибка записи документа " + ДокументСсылка + ": " + ПодробноеПредставлениеОшибки(ИнформацияОбОшибке()));
            КонецПопытки;

        КонецЕсли;

    КонецЦикла;

    Возврат ОбработаноДокументов;

КонецФункции

// Функция расчета комиссии менеджеров по проведенным заказам за период
//
// Параметры:
//  ТаблицаКомиссий - ТаблицаЗначений - таблица для заполнения результатом
//  Процент         - Число - процент комиссии (например, 0.1 для 10%)
//  ДатаС           - Дата - начало периода
//  ДатаПо          - Дата - конец периода
//
Функция РасчетКомиссииМенеджера(ТаблицаКомиссий, Процент, ДатаС, ДатаПо) Экспорт

    // Создаем таблицу значений с необходимыми колонками
    ТаблицаКомиссий = Новый ТаблицаЗначений;
    ТаблицаКомиссий.Колонки.Добавить("Менеджер",      Новый ОписаниеТипов("СправочникСсылка.Пользователи"));
    ТаблицаКомиссий.Колонки.Добавить("СуммаЗаказов",  Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
    ТаблицаКомиссий.Колонки.Добавить("Комиссия",       Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));

    // Формируем текст запроса
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Заказ.Автор КАК Менеджер,
    |    СУММА(ЗаказТовары.Сумма) КАК СуммаЗаказов
    |ИЗ
    |    Документ.Заказ.Товары КАК ЗаказТовары
    |        ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.Заказ КАК Заказ
    |        ПО ЗаказТовары.Ссылка = Заказ.Ссылка
    |ГДЕ
    |    Заказ.Дата >= &ДатаС
    |    И Заказ.Дата <= &ДатаПо
    |    И Заказ.Проведен = ИСТИНА
    |
    |СГРУППИРОВАТЬ ПО
    |    Заказ.Автор
    |
    |УПОРЯДОЧИТЬ ПО
    |    Менеджер.Наименование";

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("ДатаС",  ДатаС);
    Запрос.УстановитьПараметр("ДатаПо", КонецДня(ДатаПо));

    // Выполняем запрос
    РезультатЗапроса = Запрос.Выполнить();

    // Если результат не пустой - обходим выборку и заполняем таблицу
    Если НЕ РезультатЗапроса.Пустой() Тогда

        Выборка = РезультатЗапроса.Выбрать();

        Пока Выборка.Следующий() Цикл
            НоваяСтрока = ТаблицаКомиссий.Добавить();
            НоваяСтрока.Менеджер     = Выборка.Менеджер;
            НоваяСтрока.СуммаЗаказов = Выборка.СуммаЗаказов;
            НоваяСтрока.Комиссия     = Выборка.СуммаЗаказов * Процент;
        КонецЦикла;

    КонецЕсли;

    Возврат ТаблицаКомиссий;

КонецФункции

// Функция получает размеры изображения из JPEG файла
//
// Параметры:
//   ИмяФайла - Строка - Полный путь к файлу JPEG
//
// Возвращает:
//   Структура с ключами "Ширина" и "Высота" (размеры в пикселях)
//
// Использует объект Картинка для чтения метаданных изображения.
// Работает со стандартными и прогрессивными JPEG файлами.
//
Функция ПолучитьШиринуВысотуКартинкиИзФайлаJPEG(ИмяФайла) Экспорт

	Файл = Новый Файл(ИмяФайла);

	Если Не Файл.Существует() Тогда
		ВызватьИсключение "Файл не найден: " + ИмяФайла;
	КонецЕсли;

	Если Не Файл.ЭтоФайл() Тогда
		ВызватьИсключение "Указанный путь не является файлом: " + ИмяФайла;
	КонецЕсли;

	Попытка

		Картинка = Новый Картинка(ИмяФайла);

		// Проверяем, что картинка успешно загружена
		Если Картинка.Пустой() Тогда
			ВызватьИсключение "Не удалось загрузить изображение из файла: " + ИмяФайла;
		КонецЕсли;

		Результат = Новый Структура("Ширина, Высота", 
			Картинка.Ширина, 
			Картинка.Высота);

	Исключение

		// Если стандартный метод не сработал (например, очень большой файл),
		// используем альтернативный метод чтения напрямую из двоичных данных
		Результат = ПрочитатьРазмерыJPEGИзДвоичныхДанных(ИмяФайла);

	КонецПопытки;

	Возврат Результат;

КонецФункции

// Альтернативный метод: читает JPEG заголовок напрямую из файла
// Более эффективен для больших файлов, так как не загружает изображение в память
//
// Параметры:
//   ИмяФайла - Строка - Полный путь к файлу
//
// Возвращает:
//   Структура с ключами "Ширина" и "Высота"
//
Функция ПрочитатьРазмерыJPEGИзДвоичныхДанных(ИмяФайла)

	ДвоичныеДанные = Новый ДвоичныеДанные(ИмяФайла);
	РазмерФайла = ДвоичныеДанные.Размер();

	// Минимальный размер для JPEG файла
	Если РазмерФайла < 10 Тогда
		ВызватьИсключение "Файл слишком мал для JPEG изображения";
	КонецЕсли;

	Поток = ДвоичныеДанные.ОткрытьПотокДляЧтения();
	Чтение = Новый ЧтениеДанных(Поток);

	// Читаем начало файла: FF D8 (Start of Image marker)
	ПервыйБайт = Чтение.ПрочитатьБайт();
	ВторойБайт = Чтение.ПрочитатьБайт();

	Если ПервыйБайт <> 255 Или ВторойБайт <> 216 Тогда // 0xFF 0xD8
		ВызватьИсключение "Файл не является JPEG изображением (неверный заголовок)";
	КонецЕсли;

	// Ищем маркер SOF (Start Of Frame)
	// Допустимые маркеры: SOF0 (FFC0), SOF1 (FFC1), SOF2 (FFC2)
	// Эти маркеры содержат информацию о размерах изображения
	Пока Чтение.Позиция < РазмерФайла - 1 Цикл

		// Читаем байт маркера (ожидаем 0xFF)
		МаркерPrefix = Чтение.ПрочитатьБайт();

		Если МаркерPrefix <> 255 Тогда
			// Заполненный байт 0xFF пропускается (стандарт JPEG)
			Продолжить;
		КонецЕсли;

		Маркер = Чтение.ПрочитатьБайт();

		// Пропускаем заполненные байты
		Если Маркер = 255 Тогда
			Продолжить;
		КонецЕсли;

		// Проверяем, является ли маркер SOF
		// SOF0, SOF1, SOF2 - базовые маркеры с информацией о размерах
		Если (Маркер >= 192 И Маркер <= 207) И Маркер <> 196 Тогда

			// Читаем длину сегмента (2 байта, big-endian)
			ДлинаВысокий = Чтение.ПрочитатьБайт();
			ДлинаНизкий = Чтение.ПрочитатьБайт();
			ДлинаСегмента = (ДлинаВысокий * 256) + ДлинаНизкий;

			// Проверяем минимальную длину сегмента
			Если ДлинаСегмента < 9 Тогда
				ВызватьИсключение "Некорректная структура JPEG (сегмент SOF слишком мал)";
			КонецЕсли;

			// Пропускаем: точность (1 байт) + количество компонентов (1 байт)
			Чтение.Пропустить(2);

			// Читаем высоту (2 байта, big-endian)
			ВысотаВысокий = Чтение.ПрочитатьБайт();
			ВысотаНизкий = Чтение.ПрочитатьБайт();
			Высота = (ВысотаВысокий * 256) + ВысотаНизкий;

			// Читаем ширину (2 байта, big-endian)
			ШиринаВысокий = Чтение.ПрочитатьБайт();
			ШиринаНизкий = Чтение.ПрочитатьБайт();
			Ширина = (ШиринаВысокий * 256) + ШиринаНизкий;

			// Проверяем корректность размеров
			Если Высота <= 0 Или Ширина <= 0 Тогда
				ВызватьИсключение "Некорректные размеры изображения в JPEG файле";
			КонецЕсли;

			Чтение.Закрыть();
			Поток.Закрыть();

			Возврат Новый Структура("Ширина, Высота", Ширина, Высота);

		Иначе

			// Пропускаем текущий сегмент
			// Читаем длину сегмента (2 байта)
			ДлинаВысокий = Чтение.ПрочитатьБайт();
			ДлинаНизкий = Чтение.ПрочитатьБайт();
			ДлинаСегмента = (ДлинаВысокий * 256) + ДлинаНизкий;

			// Пропускаем оставшуюся часть сегмента
			БайтДляПропуска = ДлинаСегмента - 2;
			Если БайтДляПропуска > 0 Тогда
				Чтение.Пропустить(БайтДляПропуска);
			КонецЕсли;

		КонецЕсли;

	КонецЦикла;

	Чтение.Закрыть();
	Поток.Закрыть();

	ВызватьИсключение "Не удалось найти информацию о размерах изображения в JPEG файле";

КонецФункции

// Функция извлекает партии по методу ФИФО на заданную сумму
//
// Параметры:
//   ТаблицаПартий - ТаблицаЗначений - таблица с колонками:
//     * Партия    - Произвольный     - ссылка на партию
//     * Дата      - Дата            - дата партии
//     * Сумма     - Число           - сумма партии
//   Сумма - Число - требуемая сумма для извлечения
//
// Возвращаемое значение:
//   ТаблицаЗначений - таблица с колонками "Партия", "Дата", "Сумма"
//
Функция ИзвлечьПартииФИФО(ТаблицаПартий, Сумма) Экспорт

    // Создаём результирующую таблицу с аналогичной структурой колонок
    Результат = Новый ТаблицаЗначений;
    Результат.Колонки.Добавить("Партия");
    Результат.Колонки.Добавить("Дата");
    Результат.Колонки.Добавить("Сумма");

    // Если сумма нулевая или отрицательная — возвращаем пустую таблицу
    Если Сумма <= 0 Тогда
        Возврат Результат;
    КонецЕсли;

    // Создаём копию входной таблицы и сортируем по дате (FIFO — первыми самые ранние)
    Таблица = ТаблицаПартий.Скопировать();
    Таблица.Сортировать("Дата Возр");

    // Накапливаем сумму для определения момента достижения требуемой суммы
    НакопленнаяСумма = 0;

    Для Каждого СтрокаТаблицы Из Таблица Цикл

        // Если требуемая сумма уже достигнута — выходим из цикла
        Если НакопленнаяСумма >= Сумма Тогда
            Прервать;
        КонецЕсли;

        // Определяем остаток суммы, который необходимо покрыть
        ОстатокСуммы = Сумма - НакопленнаяСумма;

        // Проверяем, полностью ли текущая партия помещается в остаток
        Если СтрокаТаблицы.Сумма <= ОстатокСуммы Тогда

            // Партия полностью помещается — добавляем как есть
            НоваяСтрока = Результат.Добавить();
            ЗаполнитьЗначенияСвойств(НоваяСтрока, СтрокаТаблицы);
            НакопленнаяСумма = НакопленнаяСумма + СтрокаТаблицы.Сумма;

        Иначе

            // Партия превышает остаток — берём только необходимую часть
            НоваяСтрока = Результат.Добавить();
            НоваяСтрока.Партия = СтрокаТаблицы.Партия;
            НоваяСтрока.Дата   = СтрокаТаблицы.Дата;
            НоваяСтрока.Сумма  = ОстатокСуммы;
            // Накопленная сумма теперь равна требуемой — цикл завершится на следующей итерации

        КонецЕсли;

    КонецЦикла;

    Возврат Результат;

КонецФункции

// Функция добавляет в начало первой ТЗ значения из второй ТЗ 
// с обеспечением уникальности значения в колонке КолонкаУникальности
//
// Параметры:
//   Таблица1 - ТаблицаЗначений - основная таблица (заполняется)
//   Таблица2 - ТаблицаЗначений - таблица-источник строк для добавления
//   КолонкаУникальности - Строка - имя колонки для проверки уникальности
//
// Возвращаемое значение:
//   ТаблицаЗначений - дополненная таблица
//
Функция ДополнитьТаблицуЗначениямиИзВторой(Таблица1, Таблица2, КолонкаУникальности) Экспорт

    // Получаем структуру таблицы для клонирования колонок
    СтруктураКолонок = Новый Структура;
    Для Каждого Колонка Из Таблица1.Колонки Цикл
        СтруктураКолонок.Вставить(Колонка.Имя);
    КонецЦикла;

    // Создаем таблицу результата с копией колонок
    ТаблицаРезультата = Новый ТаблицаЗначений;
    Для Каждого Колонка Из Таблица1.Колонки Цикл
        ТаблицаРезультата.Колонки.Добавить(Колонка.Имя, Колонка.ТипЗначения);
    КонецЦикла;

    // Строим соответствие значений из первой таблицы для быстрой проверки дубликатов
    СоответствиеУникальности = Новый Соответствие;

    Для Каждого Строка Из Таблица1 Цикл
        ЗначениеКлюча = Строка[КолонкаУникальности];
        СоответствиеУникальности.Вставить(ЗначениеКлюча, Истина);
    КонецЦикла;

    // Добавляем строки из второй таблицы (без дубликатов) в начало результата
    Для Каждого СтрокаТ2 Из Таблица2 Цикл

        ЗначениеКлюча = СтрокаТ2[КолонкаУникальности];

        // Пропускаем строки с дублирующимися значениями
        Если СоответствиеУникальности[ЗначениеКлюча] <> Неопределено Тогда
            Продолжить;
        КонецЕсли;

        // Добавляем строку в результат
        НоваяСтрока = ТаблицаРезультата.Добавить();
        ЗаполнитьЗначенияСвойств(НоваяСтрока, СтрокаТ2);

        // Добавляем значение в соответствие, чтобы избежать дубликатов
        // в оставшихся строках второй таблицы
        СоответствиеУникальности.Вставить(ЗначениеКлюча, Истина);

    КонецЦикла;

    // Добавляем все строки из первой таблицы в конец результата
    Для Каждого СтрокаТ1 Из Таблица1 Цикл

        НоваяСтрока = ТаблицаРезультата.Добавить();
        ЗаполнитьЗначенияСвойств(НоваяСтрока, СтрокаТ1);

    КонецЦикла;

    Возврат ТаблицаРезультата;

КонецФункции

