//
Функция ОбойтиСтруктуруКД(СтруктураКД, ИмяПоля, ЧастиПоля, ВключаяВложенныеПоля)

    Если СтруктураКД = Неопределено Тогда
        Возврат Ложь;
    Коне

// Функция формирует список покупателей с положительной дебиторской задолженностью
//
// Параметры:
//   ДатаНач - Дата - дата начала периода анализа (по умолчанию - начало текущего года)
//   ДатаКон - Дата - дата окончания периода анализа (по умолчанию - конец текущего дня)
//
// Возвращает:
//   ТаблицаЗначений - с колонками:
//     Покупатель   - ссылка на контрагента
//     СуммаДолга   - сумма дебиторской задолженности
//
Функция СформироватьКонтрольЗадержкиОплаты(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка значений по умолчанию
    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоГода(ТекущаяДата());
    КонецЕсли;

    // Создание запроса
    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ
    |    ВзаиморасчетыОбороты.Контрагент КАК Покупатель,
    |    СУММА(ВзаиморасчетыОбороты.СуммаОборот) КАК СуммаДолга
    |ИЗ
    |    РегистрНакопления.Взаиморасчеты.Обороты(&ДатаНач, &ДатаКон, Запись, Контрагент) КАК ВзаиморасчетыОбороты
    |
    |СГРУППИРОВАТЬ ПО
    |    ВзаиморасчетыОбороты.Контрагент
    |
    |ИМЕЮЩИЕ
    |    СУММА(ВзаиморасчетыОбороты.СуммаОборот) > 0
    |
    |УПОРЯДОЧИТЬ ПО
    |    СуммаДолга УБЫВ";

    // Установка параметров запроса
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    // Выполнение запроса и возврат результата
    РезультатЗапроса = Запрос.Выполнить();
    ТаблицаЗадолженности = РезультатЗапроса.Выгрузить();

    Возврат ТаблицаЗадолженности;

КонецФункции

// СформироватьИсториюДвиженияТовара
//
// Параметры:
//   Товар - СправочникСсылка.Товары, Массив - Товар или список товаров
//   ДатаНач - Дата - Дата начала периода (по умолчанию - начало текущего года)
//   ДатаКон - Дата - Дата окончания периода (по умолчанию - конец текущего дня)
//
// Возвращает:
//   ТаблицаЗначений - История движения товара с колонками: Дата, ВидДвижения, Товар, Количество, Сумма
//
Функция СформироватьИсториюДвиженияТовара(Товар, ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка параметров периода
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоГода(ТекущаяДата());
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Подготовка параметра Товар (поддержка как одиночного значения, так и массива)
    Если ТипЗнч(Товар) = Тип("СправочникСсылка.Товары") Тогда
        МассивТоваров = Новый Массив;
        МассивТоваров.Добавить(Товар);
    ИначеЕсли ТипЗнч(Товар) = Тип("Массив") Тогда
        МассивТоваров = Товар;
    Иначе
        МассивТоваров = Новый Массив;
    КонецЕсли;

    // Создание таблицы результата
    Результат = Новый ТаблицаЗначений;
    Результат.Колонки.Добавить("Дата", Новый ОписаниеТипов("Дата", , ,
        Новый КвалификаторыДаты(ЧастиДаты.ДатаВремя)));
    Результат.Колонки.Добавить("ВидДвижения", Новый ОписаниеТипов("Строка", ,
        Новый КвалификаторыСтроки(10)));
    Результат.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    Результат.Колонки.Добавить("Количество", Новый ОписаниеТипов("Число", ,
        Новый КвалификаторыЧисла(10, 2)));
    Результат.Колонки.Добавить("Сумма", Новый ОписаниеТипов("Число", ,
        Новый КвалификаторыЧисла(10, 2)));

    // Формирование текста запроса
    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ
    |    ПриходТовараТовары.Ссылка.Дата КАК Дата,
    |    ""Приход"" КАК ВидДвижения,
    |    ПриходТовараТовары.Товар,
    |    ПриходТовараТовары.Количество,
    |    ПриходТовараТовары.Сумма
    |ИЗ
    |    Документ.ПриходТовара.Товары КАК ПриходТовараТовары
    |ГДЕ
    |    ПриходТовараТовары.Ссылка.Дата >= &ДатаНач
    |    И ПриходТовараТовары.Ссылка.Дата <= &ДатаКон
    |    И ПриходТовараТовары.Ссылка.Проведен
    |    И ПриходТовараТовары.Товар В (&Товар)
    |
    |ОБЪЕДИНИТЬ ВСЕ
    |
    |ВЫБРАТЬ
    |    РасходТовараТовары.Ссылка.Дата,
    |    ""Расход"",
    |    РасходТовараТовары.Товар,
    |    РасходТовараТовары.Количество,
    |    РасходТовараТовары.Сумма
    |ИЗ
    |    Документ.РасходТовара.Товары КАК РасходТовараТовары
    |ГДЕ
    |    РасходТовараТовары.Ссылка.Дата >= &ДатаНач
    |    И РасходТовараТовары.Ссылка.Дата <= &ДатаКон
    |    И РасходТовараТовары.Ссылка.Проведен
    |    И РасходТовараТовары.Товар В (&Товар)
    |
    |УПОРЯДОЧИТЬ ПО Дата";

    // Установка параметров запроса
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);
    Запрос.УстановитьПараметр("Товар", МассивТоваров);

    // Выполнение запроса
    РезультатЗапроса = Запрос.Выполнить();

    // Выгрузка результата в таблицу значений
    Если Не РезультатЗапроса.Пустой() Тогда
        Результат = РезультатЗапроса.Выгрузить();
    КонецЕсли;

    Возврат Результат;

КонецФункции

// Функция выполняет XYZ-анализ продаж товаров.
// Определяет стабильность спроса на каждый товар путем расчёта
// коэффициента вариации месячных продаж и присваивает категорию X, Y или Z.
//
// Параметры:
//   ДатаНач - Дата - Дата начала периода анализа (по умолчанию 12 месяцев назад)
//   ДатаКон - Дата - Дата окончания периода анализа (по умолчанию конец текущего дня)
//
// Возвращает:
//   ТаблицаЗначений - Результат XYZ-анализа с колонками:
//     Товар - СправочникСсылка.Товары
//     СредниеПродажи - Среднемесячное количество продаж
//     ОтклонениеПродаж - Стандартное отклонение продаж
//     КоэффициентВариации - Коэффициент вариации (чем меньше — тем стабильнее)
//     XYZКатегория - Категория XYZ-анализа ("X", "Y" или "Z")
//
Функция СформироватьXYZАнализПродаж(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка параметров по умолчанию
    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоМесяца(ДобавитьМесяц(ТекущаяДата(), -12));
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала!";
    КонецЕсли;

    // Создание запроса и установка параметров
    Запрос = Новый Запрос;
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    // Формирование текста запроса для получения месячных продаж товаров
    Запрос.Текст =
    "ВЫБРАТЬ
    |    ПродажиТовары.Товар КАК Товар,
    |    НАЧАЛОПЕРИОДА(РасходТовара.Дата, МЕСЯЦ) КАК МесяцПродаж,
    |    СУММА(ПродажиТовары.Количество) КАК КоличествоПродаж
    |ИЗ
    |    Документ.РасходТовара.Товары КАК ПродажиТовары
    |        ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.РасходТовара КАК РасходТовара
    |        ПО ПродажиТовары.Ссылка = РасходТовара.Ссылка
    |ГДЕ
    |    РасходТовара.Дата >= &ДатаНач
    |    И РасходТовара.Дата <= &ДатаКон
    |    И РасходТовара.Проведен
    |СГРУППИРОВАТЬ ПО
    |    ПродажиТовары.Товар,
    |    НАЧАЛОПЕРИОДА(РасходТовара.Дата, МЕСЯЦ)
    |
    |УПОРЯДОЧИТЬ ПО
    |    Товар,
    |    МесяцПродаж";

    // Выполнение запроса и получение результата
    РезультатЗапроса = Запрос.Выполнить();

    // Создание таблицы значений для результата анализа
    Результат = Новый ТаблицаЗначений;
    Результат.Колонки.Добавить("Товар");
    Результат.Колонки.Добавить("СредниеПродажи");
    Результат.Колонки.Добавить("ОтклонениеПродаж");
    Результат.Колонки.Добавить("КоэффициентВариации");
    Результат.Колонки.Добавить("XYZКатегория");

    // Обход результатов и расчёт показателей для каждого товара
    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл

        // Инициализация переменных для расчёта статистики
        СуммаКоличеств = 0;
        СуммаКвадратов = 0;
        КоличествоМесяцев = 0;

        ТекущийТовар = Выборка.Товар;

        // Накопление данных по месяцам для текущего товара
        Пока Выборка.Товар = ТекущийТовар Цикл

            Количество = Выборка.КоличествоПродаж;
            СуммаКоличеств = СуммаКоличеств + Количество;
            СуммаКвадратов = СуммаКвадратов + (Количество * Количество);
            КоличествоМесяцев = КоличествоМесяцев + 1;

            Если НЕ Выборка.Следующий() Тогда
                Прервать;
            КонецЕсли;

        КонецЦикла;

        // Расчёт среднего значения продаж
        СредниеПродажи = ?(КоличествоМесяцев > 0, СуммаКоличеств / КоличествоМесяцев, 0);

        // Расчёт стандартного отклонения (дисперсия = среднее квадратов - квадрат среднего)
        Если КоличествоМесяцев > 0 Тогда
            СреднийКвадрат = СуммаКвадратов / КоличествоМесяцев;
            Дисперсия = Макс(0, СреднийКвадрат - (СредниеПродажи * СредниеПродажи));
            ОтклонениеПродаж = Sqrt(Дисперсия);
        Иначе
            ОтклонениеПродаж = 0;
        КонецЕсли;

        // Расчёт коэффициента вариации и определение категории XYZ
        Если СредниеПродажи = 0 Тогда
            XYZКатегория = "";
        Иначе
            КоэффициентВариации = ОтклонениеПродаж / СредниеПродажи;

            // Присвоение категории на основе коэффициента вариации
            // X — Коэффициент вариации <= 0,10 (очень стабильный спрос)
            // Y — Коэффициент вариации <= 0,25 (средняя стабильность)
            // Z — Коэффициент вариации > 0,25 (нестабильный спрос)
            Если КоэффициентВариации <= 0.10 Тогда
                XYZКатегория = "X";
            ИначеЕсли КоэффициентВариации <= 0.25 Тогда
                XYZКатегория = "Y";
            Иначе
                XYZКатегория = "Z";
            КонецЕсли;
        КонецЕсли;

        // Добавление строки с результатами анализа товара
        НоваяСтрока = Результат.Добавить();
        НоваяСтрока.Товар = ТекущийТовар;
        НоваяСтрока.СредниеПродажи = СредниеПродажи;
        НоваяСтрока.ОтклонениеПродаж = ОтклонениеПродаж;
        НоваяСтрока.КоэффициентВариации = ?(СредниеПродажи > 0, ОтклонениеПродаж / СредниеПродажи, 0);
        НоваяСтрока.XYZКатегория = XYZКатегория;

    КонецЦикла;

    Возврат Результат;

КонецФункции

task:
Написать функцию СформироватьПродажиПоДнямНедели(ДатаНач, ДатаКон), которая формирует отчет о продажах предприятия с разбивкой по 
дням недели за выбранный период.
Задача предназначена для анализа покупательской активности и позволяет определить, в какие дни недели наблюдаются наибольшие продажи.

Результаты анализа могут использоваться для:
оптимизации графика работы персонала;
планирования акций и маркетинговых мероприятий;
анализа нагрузки на торговые точки;
выявления пиковых и слабых дней продаж;
повышения эффективности управления продажами.

Параметры функции:
ДатаНач — дата начала периода анализа;
ДатаКон — дата окончания периода анализа.

Если параметры периода не заданы, используются значения по умолчанию:
ДатаНач = начало дня 30 дней назад;
ДатаКон = конец текущего дня.

Перед выполнением расчета выполняется проверка параметров:
если ДатаКон < ДатаНач — генерируется исключение;
анализ выполняется только в пределах указанного периода.

Расчет выполняется на основании регистра накопления Продажи.
Используются следующие поля:
Период — дата продажи;
Количество — количество проданного товара;
Сумма — сумма продаж.

В процессе выполнения:
определяется день недели по дате продажи;
выполняется группировка по дням недели;
рассчитываются итоговые показатели по количеству и сумме продаж;
формируется итоговая таблица значений.

Результат функции представляет собой таблицу, содержащую:
день недели;
общее количество продаж;
общую сумму продаж.

output:
// Функция формирует отчет о продажах по дням недели
//
// Параметры:
//   ДатаНач - Дата - Дата начала периода анализа (по умолчанию: 30 дней назад)
//   ДатаКон - Дата - Дата окончания периода анализа (по умолчанию: конец текущего дня)
//
// Возвращаемое значение:
//   ТаблицаЗначений - таблица с колонками:
//     * ДеньНедели - Строка - Название дня недели
//     * НомерДняНедели - Число - Номер дня недели (1-Пн, 7-Вс)
//     * Количество - Число - Общее количество продаж
//     * Сумма - Число - Общая сумма продаж
//
// исключения:
//   - Если дата окончания меньше даты начала периода
//
Функция СформироватьПродажиПоДнямНедели(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка параметров по умолчанию, если не переданы
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДата()) - 30 * 86400; // 30 дней назад
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата()); // Конец текущего дня
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала периода.";
    КонецЕсли;

    // Формирование запроса к регистру накопления Продажи
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |   ВЫБОР
    |       КОГДА ДЕНЬНЕДЕЛИ(ПродажиОбороты.Период) = 1
    |           ТОГДА ""Понедельник""
    |       КОГДА ДЕНЬНЕДЕЛИ(ПродажиОбороты.Период) = 2
    |           ТОГДА ""Вторник""
    |       КОГДА ДЕНЬНЕДЕЛИ(ПродажиОбороты.Период) = 3
    |           ТОГДА ""Среда""
    |       КОГДА ДЕНЬНЕДЕЛИ(ПродажиОбороты.Период) = 4
    |           ТОГДА ""Четверг""
    |       КОГДА ДЕНЬНЕДЕЛИ(ПродажиОбороты.Период) = 5
    |           ТОГДА ""Пятница""
    |       КОГДА ДЕНЬНЕДЕЛИ(ПродажиОбороты.Период) = 6
    |           ТОГДА ""Суббота""
    |       КОГДА ДЕНЬНЕДЕЛИ(ПродажиОбороты.Период) = 7
    |           ТОГДА ""Воскресенье""
    |   КОНЕЦ КАК ДеньНедели,
    |   ДЕНЬНЕДЕЛИ(ПродажиОбороты.Период) КАК НомерДняНедели,
    |   СУММА(ПродажиОбороты.КоличествоОборот) КАК Количество,
    |   СУММА(ПродажиОбороты.СуммаОборот) КАК Сумма
    |ИЗ
    |   РегистрНакопления.Продажи.Обороты(&ДатаНач, &ДатаКон, Авто, ) КАК ПродажиОбороты
    |
    |СГРУППИРОВАТЬ ПО
    |   ДЕНЬНЕДЕЛИ(ПродажиОбороты.Период)
    |
    |УПОРЯДОЧИТЬ ПО
    |   НомерДняНедели";

    // Установка параметров запроса
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    // Выполнение запроса
    РезультатЗапроса = Запрос.Выполнить();

    // Создание таблицы значений для результата
    ТаблицаРезультата = Новый ТаблицаЗначений;
    ТаблицаРезультата.Колонки.Добавить("ДеньНедели", Новый ОписаниеТипов("Строка", , Новый КвалификаторыСтроки(15)));
    ТаблицаРезультата.Колонки.Добавить("НомерДняНедели", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(1)));
    ТаблицаРезультата.Колонки.Добавить("Количество", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 3)));
    ТаблицаРезультата.Колонки.Добавить("Сумма", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(18, 2)));

    // Обход результата запроса и заполнение таблицы значений
    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        СтрокаРезультата = ТаблицаРезультата.Добавить();
        СтрокаРезультата.ДеньНедели = Выборка.ДеньНедели;
        СтрокаРезультата.НомерДняНедели = Выборка.НомерДняНедели;
        СтрокаРезультата.Количество = Выборка.Количество;
        СтрокаРезультата.Сумма = Выборка.Сумма;
    КонецЦикла;

    // Сортировка по номеру дня недели (для гарантированного порядка)
    ТаблицаРезультата.Сортировать("НомерДняНедели ВОЗР");

    Возврат ТаблицаРезультата;

КонецФункции

task:
Написать функцию СформироватьТоварыБезДвижения(ДатаНач, ДатаКон), которая формирует список товаров, по которым отсутствовали движения (продажи) 
за выбранный период.
Задача предназначена для анализа ассортимента и позволяет выявить товары, не участвующие в продажах.

Результаты анализа могут использоваться для:
выявления неликвидных и залежалых товаров;
принятия решений о скидках или акциях;
оптимизации ассортимента;
освобождения складских запасов;
повышения оборачиваемости товаров.

Параметры функции:
ДатаНач — дата начала периода анализа;
ДатаКон — дата окончания периода анализа.

Если параметры периода не заданы, используются значения по умолчанию:
ДатаНач = начало дня 30 дней назад;
ДатаКон = конец текущего дня.

Перед выполнением расчета выполняется проверка параметров:
если ДатаКон < ДатаНач — генерируется исключение;
анализ выполняется только в пределах указанного периода.

Расчет выполняется на основании следующих объектов конфигурации:
Справочник Товары — используется для получения полного списка товаров;
Регистр накопления Продажи — используется для определения наличия движений по товарам.

В процессе выполнения:
формируется список всех товаров без пометки удаления;
определяются товары, по которым были продажи за указанный период;
выполняется сравнение списков;
отбираются товары, по которым отсутствуют движения.

Результат функции представляет собой таблицу значений, содержащую:
товар;
наименование товара.

Полученный список позволяет оперативно выявить товары без движения и принять управленческие решения.

output:
// Функция формирует список товаров без движения (продаж) за указанный период
//
// Параметры:
//   ДатаНач - Дата - Дата начала периода анализа (по умолчанию: начало дня 30 дней назад)
//   ДатаКон - Дата - Дата окончания периода анализа (по умолчанию: конец текущего дня)
//
// Возвращает:
//   ТаблицаЗначений - с колонками:
//     * Товар - СправочникСсылка.Товары - ссылка на товар
//     * Наименование - Строка - наименование товара
//
// Исключения:
//   - Если ДатаКон < ДатаНач вызывается исключение
//
Функция СформироватьТоварыБезДвижения(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка параметров по умолчанию
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДатаСеанса()) - 30 * 86400;
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДатаСеанса());
    КонецЕсли;

    // Проверка параметров периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала периода";
    КонецЕсли;

    // Формирование результата
    Результат = Новый ТаблицаЗначений;
    Результат.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    Результат.Колонки.Добавить("Наименование", Новый ОписаниеТипов("Строка"));

    // Формирование запроса
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Товары.Ссылка КАК Товар,
    |    Товары.Наименование КАК Наименование
    |ИЗ
    |    Справочник.Товары КАК Товары
    |ГДЕ
    |    Товары.ПометкаУдаления = ЛОЖЬ
    |    И НЕ Товары.Ссылка В
    |        (ВЫБРАТЬ
    |            Продажи.Товар
    |        ИЗ
    |            РегистрНакопления.Продажи.Обороты(&ДатаНач, &ДатаКон, , ) КАК Продажи
    |        ГДЕ
    |            Продажи.КоличествоОборот <> 0)
    |УПОРЯДОЧИТЬ ПО
    |    Товары.Наименование";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    РезультатЗапроса = Запрос.Выполнить();
    Если Не РезультатЗапроса.Пустой() Тогда
        Результат = РезультатЗапроса.Выгрузить();
    КонецЕсли;

    Возврат Результат;

КонецФункции

task:
Написать функцию НайтиПревышениеЛимитаПродаж(ДатаНач, ДатаКон, Лимит),
которая формирует список документов продаж предприятия, у которых сумма документа превышает установленный лимит за выбранный период.

Функция принимает три параметра:

ДатаНач — дата начала периода анализа;
ДатаКон — дата окончания периода анализа;
Лимит — максимальная допустимая сумма документа.

Если параметры периода не заданы, функция должна автоматически установить:

ДатаНач = начало дня 30 дней назад  
ДатаКон = конец текущего дня
Если параметр Лимит не задан — может использоваться значение по умолчанию


Перед выполнением расчета необходимо выполнить проверки:

если ДатаКон < ДатаНач — должно быть сгенерировано исключение;
если даты не заданы — используются значения по умолчанию;
анализ выполняется только в пределах указанного период 

Расчет выполняется на основании следующих объектов конфигурации:
Документ.РасходТовара

Функция должна возвращать объект типа ТаблицаЗначений, содержащий:

Ссылка — ссылка на документ;
Дата — дата документа;
Покупатель — контрагент;
Сумма — сумма документа

output:
// Функция формирует список документов продаж,
// сумма которых превышает установленный лимит
//
// Параметры:
//   ДатаНач - Дата - Дата начала периода анализа (необязательно)
//   ДатаКон - Дата - Дата окончания периода анализа (необязательно)
//   Лимит - Число - Максимальная допустимая сумма документа (необязательно)
//
// Возвращаемое значение:
//   ТаблицаЗначений - содержит колонки: Ссылка, Дата, Покупатель, Сумма
//
// Пример использования:
//   ТаблицаПревышений = НайтиПревышениеЛимитаПродаж(
//       '2024.01.01', 
//       '2024.01.31', 
//       100000
//   );
//
Функция НайтиПревышениеЛимитаПродаж(ДатаНач = Неопределено, 
                                    ДатаКон = Неопределено, 
                                    Лимит = Неопределено) Экспорт

    // Установка значений по умолчанию для периода
    ТекущаяДата = ТекущаяДатаСеанса();

    // Если дата начала не задана - устанавливаем начало дня 30 дней назад
    Если НЕ ЗначениеЗаполнено(ДатаНач) Тогда
        ДатаНач = НачалоДня(ТекущаяДата - 30 * 86400); // 86400 секунд = 1 день
    КонецЕсли;

    // Если дата окончания не задана - устанавливаем конец текущего дня
    Если НЕ ЗначениеЗаполнено(ДатаКон) Тогда
        ДатаКон = КонецДня(ТекущаяДата);
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала!";
    КонецЕсли;

    // Если лимит не задан - устанавливаем значение по умолчанию
    Если НЕ ЗначениеЗаполнено(Лимит) Тогда
        Лимит = 0; // При значении 0 фильтрация по лимиту не применяется
    КонецЕсли;

    // Создание запроса для получения данных
    Запрос = Новый Запрос;

    // Установка параметров запроса
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);
    Запрос.УстановитьПараметр("Лимит",   Лимит);

    // Формирование текста запроса
    Запрос.Текст =
    "ВЫБРАТЬ
    |    РасходТовара.Ссылка КАК Ссылка,
    |    РасходТовара.Дата КАК Дата,
    |    РасходТовара.Покупатель КАК Покупатель,
    |    РасходТовараТовары.Ссылка.СуммаДокумента КАК Сумма
    |ИЗ
    |    Документ.РасходТовара КАК РасходТовара
    |        ЛЕВОЕ СОЕДИНЕНИЕ Документ.РасходТовара.Товары КАК РасходТовараТовары
    |        ПО РасходТовара.Ссылка = РасходТовараТовары.Ссылка
    |ГДЕ
    |    РасходТовара.Дата >= &ДатаНач
    |    И РасходТовара.Дата <= &ДатаКон
    |    И РасходТовара.Проведен = ИСТИНА
    |    И ВЫБОР
    |            КОГДА &Лимит > 0
    |                ТОГДА РасходТовара.СуммаДокумента > &Лимит
    |            ИНАЧЕ ИСТИНА
    |        КОНЕЦ
    |
    |СГРУППИРОВАТЬ ПО
    |    РасходТовара.Ссылка,
    |    РасходТовара.Дата,
    |    РасходТовара.Покупатель,
    |    РасходТовара.СуммаДокумента
    |
    |УПОРЯДОЧИТЬ ПО
    |    РасходТовара.Дата УБЫВ";

    // Выполнение запроса и получение результата
    РезультатЗапроса = Запрос.Выполнить();

    // Создание таблицы значений для результата
    ТаблицаРезультат = Новый ТаблицаЗначений;

    // Если запрос вернул данные - выгружаем их
    Если НЕ РезультатЗапроса.Пустой() Тогда
        ТаблицаРезультат = РезультатЗапроса.Выгрузить();
    Иначе
        // Создание структуры колонок для пустой таблицы
        ТаблицаРезультат.Колонки.Добавить("Ссылка",    Новый ОписаниеТипов("ДокументСсылка.РасходТовара"));
        ТаблицаРезультат.Колонки.Добавить("Дата",      Новый ОписаниеТипов("Дата", , , Новый КвалификаторыДаты(ЧастиДаты.Дата)));
        ТаблицаРезультат.Колонки.Добавить("Покупатель",Новый ОписаниеТипов("СправочникСсылка.Контрагенты"));
        ТаблицаРезультат.Колонки.Добавить("Сумма",     Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
    КонецЕсли;

    Возврат ТаблицаРезультат;

КонецФункции // НайтиПревышениеЛимитаПродаж()

Функция СформироватьОтчетОстаткиТоваровКонтроль(Период, КоличествоКонтроль) Экспорт

    // Создаем объект отчета
    ОтчетОбъект = Отчеты.ОстаткиТоваровНаСкладах.Создать();

    // Получаем схему компоновки данных
    СхемаКомпоновкиДанных = ОтчетОбъект.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Создаем и инициализируем компоновщик настроек
    ИсточникНастроек = Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновкиДанных);
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(ИсточникНастроек);

    // Загружаем вариант отчета "Основной"
    ВариантЗагружен = Ложь;
    Для Каждого Вариант Из СхемаКомпоновкиДанных.ВариантыНастроек Цикл
        Если НРег(Вариант.Имя) = "основной" Тогда
            КомпоновщикНастроек.ЗагрузитьНастройки(Вариант.Настройки);
            ВариантЗагружен = Истина;
            Прервать;
        КонецЕсли;
    КонецЦикла;

    // Если вариант не найден, загружаем настройки по умолчанию
    Если Не ВариантЗагружен Тогда
        КомпоновщикНастроек.ЗагрузитьНастройки(СхемаКомпоновкиДанных.НастройкиПоУмолчанию);
    КонецЕсли;

    // Получаем настройки
    Настройки = КомпоновщикНастроек.Настройки;

    // Устанавливаем параметры вывода
    Настройки.ПараметрыВывода.УстановитьЗначениеПараметра(
        "ВыводитьПараметрыДанных", 
        ТипВыводаТекстаКомпоновкиДанных.НеВыводить
    );
    Настройки.ПараметрыВывода.УстановитьЗначениеПараметра(
        "ВыводитьОтбор", 
        ТипВыводаТекстаКомпоновкиДанных.НеВыводить
    );

    // Устанавливаем параметр периода
    // Ищем параметр периода в доступных параметрах
    ИмяПараметраПериода = "";

    Для Каждого Параметр Из СхемаКомпоновкиДанных.Параметры Цикл
        Если НРег(Параметр.Имя) = "стандартнаядатаначала"
            Или НРег(Параметр.Имя) = "период"
            Или НРег(Параметр.Имя) = "датаначала"
            Или НРег(Параметр.Имя) = "конечнаядата" Тогда
            ИмяПараметраПериода = Параметр.Имя;
            Прервать;
        КонецЕсли;
    КонецЦикла;

    // Устанавливаем значение параметра периода
    Если ИмяПараметраПериода <> "" Тогда
        ПараметрПериода = Настройки.ПараметрыДанных.НайтиЗначениеПараметра(
            Новый ПараметрКомпоновкиДанных(ИмяПараметраПериода)
        );
        Если ПараметрПериода <> Неопределено Тогда
            ПараметрПериода.Значение = Период;
            ПараметрПериода.Использование = Истина;
        КонецЕсли;
    КонецЕсли;

    // Устанавливаем отбор по количеству остатка
    // Удаляем все существующие отборы
    Настройки.Отбор.Элементы.Очистить();

    // Добавляем новый элемент отбора
    ЭлементОтбора = Настройки.Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("КоличествоОстаток");
    ЭлементОтбора.ВидСравнения = ВидСравненияКомпоновкиДанных.МеньшеИлиРавно;
    ЭлементОтбора.ПравоеЗначение = КоличествоКонтроль;
    ЭлементОтбора.Использование = Истина;

    // Получаем пользовательские настройки для модификации структуры
    ПользовательскиеНастройки = КомпоновщикНастроек.ПользовательскиеНастройки;

    // Находим табличную структуру
    ТабличнаяСтруктура = Неопределено;

    // Сначала ищем в пользовательских настройках
    Для Каждого Элемент Из ПользовательскиеНастройки.Элементы Цикл
        Если ТипЗнч(Элемент) = Тип("ТаблицаКомпоновкиДанных") Тогда
            ТабличнаяСтруктура = Элемент;
            Прервать;
        КонецЕсли;
    КонецЦикла;

    // Если не найдена, создаем новую табличную структуру
    Если ТабличнаяСтруктура = Неопределено Тогда
        // Добавляем таблицу в пользовательские настройки
        ТабличнаяСтруктура = ПользовательскиеНастройки.Элементы.Добавить(
            Тип("ТаблицаКомпоновкиДанных")
        );
    КонецЕсли;

    // Настраиваем структуру таблицы
    // Строки: Товар
    ТабличнаяСтруктура.Строки.Очистить();
    ГруппировкаСтроки = ТабличнаяСтруктура.Строки.Добавить();
    ГруппировкаСтроки.Поле = Новый ПолеКомпоновкиДанных("Товар");
    ГруппировкаСтроки.Использование = Истина;

    // Колонки: Склад
    ТабличнаяСтруктура.Колонки.Очистить();
    ГруппировкаКолонки = ТабличнаяСтруктура.Колонки.Добавить();
    ГруппировкаКолонки.Поле = Новый ПолеКомпоновкиДанных("Склад");
    ГруппировкаКолонки.Использование = Истина;

    // Настраиваем выбранные поля таблицы
    ТабличнаяСтруктура.Выбор.Элементы.Очистить();

    // КоличествоОстаток
    ПолеКоличество = ТабличнаяСтруктура.Выбор.Элементы.Добавить(
        Тип("ВыбранноеПолеКомпоновкиДанных")
    );
    ПолеКоличество.Поле = Новый ПолеКомпоновкиДанных("КоличествоОстаток");
    ПолеКоличество.Использование = Истина;

    // Товар
    ПолеТовар = ТабличнаяСтруктура.Выбор.Элементы.Добавить(
        Тип("ВыбранноеПолеКомпоновкиДанных")
    );
    ПолеТовар.Поле = Новый ПолеКомпоновкиДанных("Товар");
    ПолеТовар.Использование = Истина;

    // Склад
    ПолеСклад = ТабличнаяСтруктура.Выбор.Элементы.Добавить(
        Тип("ВыбранноеПолеКомпоновкиДанных")
    );
    ПолеСклад.Поле = Новый ПолеКомпоновкиДанных("Склад");
    ПолеСклад.Использование = Истина;

    // Формируем отчет
    ТабличныйДокумент = Новый ТабличныйДокумент;

    // Получаем финальные настройки
    ФинальныеНастройки = КомпоновщикНастроек.ПолучитьНастройки();

    // Выполняем компоновку данных
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(
        СхемаКомпоновкиДанных,
        ФинальныеНастройки,
        ,
        ,
        Тип("ГенераторМакетаКомпоновкиДанных")
    );

    // Создаем процессоры компоновки
    ПроцессорКомпоновкиДанных = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновкиДанных.Инициализировать(МакетКомпоновки);

    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновкиДанных);

    Возврат ТабличныйДокумент;

КонецФункции

// Функция добавляет получателей в исходящие письма
//
// Параметры:
//  Получатели - Массив из СправочникСсылка.Контрагенты - контрагенты-получатели
//  Дата - Дата - дата, больше которой должны быть выбраны письма
//
// Возвращаемое значение:
//  Число - количество обработанных писем
//
Функция ДобавитьПолучателейИсходящихПисем(Получатели, Дата) Экспорт

    // Получаем массив email-адресов контрагентов
    ЗапросEmail = Новый Запрос;
    ЗапросEmail.УстановитьПараметр("МассивПолучателей", Получатели);
    ЗапросEmail.Текст =
    "ВЫБРАТЬ
    |	Контрагенты.Ссылка КАК Контрагент,
    |	Контрагенты.ЭлектроннаяПочта КАК ЭлектроннаяПочта
    |ИЗ
    |	Справочник.Контрагенты КАК Контрагенты
    |ГДЕ
    |	Контрагенты.Ссылка В (&МассивПолучателей)
    |	И Контрагенты.ЭлектроннаяПочта <> """"
    |	И Контрагенты.ЭлектроннаяПочта <> """";

    ТаблицаПолучателей = ЗапросEmail.Выполнить().Выгрузить();

    // Если нет получателей с заполненными email, возвращаем 0
    Если ТаблицаПолучателей.Количество() = 0 Тогда
        Возврат 0;
    КонецЕсли;

    // Формируем запрос для выборки неотправленных писем
    Запрос = Новый Запрос;
    Запрос.УстановитьПараметр("МассивПолучателей", Получатели);
    Запрос.УстановитьПараметр("Дата", Дата);
    Запрос.Текст =
    "ВЫБРАТЬ
    |	ИсходящиеПисьма.Ссылка КАК Письмо
    |ИЗ
    |	Справочник.ИсходящиеПисьма КАК ИсходящиеПисьма
    |ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.СостояниеИсходящихПисем КАК СостояниеИсходящихПисем
    |ПО ИсходящиеПисьма.Ссылка = СостояниеИсходящихПисем.Письмо
    |ГДЕ
    |	ИсходящиеПисьма.Дата > &Дата
    |	И НЕ ИсходящиеПисьма.ПометкаУдаления
    |	И ИсходящиеПисьма.Контрагент В (&МассивПолучателей)
    |	И (СостояниеИсходящихПисем.Письмо ЕСТЬ NULL
    |		ИЛИ НЕ СостояниеИсходящихПисем.Отправлено)
    |УПОРЯДОЧИТЬ ПО
    |	ИсходящиеПисьма.Дата УБЫВ";

    РезультатЗапроса = Запрос.Выполнить();

    // Если писем не найдено, возвращаем 0
    Если РезультатЗапроса.Пустой() Тогда
        Возврат 0;
    КонецЕсли;

    // Обрабатываем найденные письма
    Выборка = РезультатЗапроса.Выбрать();
    КоличествоОбработанных = 0;

    Пока Выборка.Следующий() Цикл

        ПисьмоОбъект = Выборка.Письмо.ПолучитьОбъект();

        // Проверяем, что объект не заблокирован
        Если НجوтоеЗначение(ПисьмоОбъект) = Неопределено Тогда
            Продолжить;
        КонецЕсли;

        // Очищаем табличную часть перед заполнением
        ПисьмоОбъект.Покупатели.Очистить();

        // Заполняем табличную часть данными о получателях
        Для Каждого СтрокаПолучателя Из ТаблицаПолучателей Цикл

            НоваяСтрока = ПисьмоОбъект.Покупатели.Добавить();
            НоваяСтрока.ЭлектроннаяПочта = СтрокаПолучателя.ЭлектроннаяПочта;

        КонецЦикла;

        // Записываем письмо
        Попытка
            ПисьмоОбъект.Записать();
            КоличествоОбработанных = КоличествоОбработанных + 1;
        Исключение
            // Логируем ошибку записи
            ЗаписьЖурналаРегистрации(
                "ДобавитьПолучателейИсходящихПисем",
                УровеньЖурналаРегистрации.Ошибка,
                ,
                ,
                "Ошибка записи письма: " + ПодробноеПредставлениеОшибки(ИнформацияОбОшибке())
            );
        КонецПопытки;

    КонецЦикла;

    Возврат КоличествоОбработанных;

КонецФункции
